import os
d = os.environ['RLM_SESSION_DIR']
session_file = os.path.join(d, '../../sessions/', os.path.basename(d), '.jsonl')

# Search for "Test input"
with open(session_file) as f:
    content = f.read()

print("Looking for 'Test input' in session:")
lines = content.split('\n')
for i, line in enumerate(lines):
    if 'Test input' in line:
        print(f"\nFound at line {i}")
        print(f"Line: {line[:300]}")
        # Print surrounding context
        start = max(0, i-2)
        end = min(len(lines), i+30)
        for j in range(start, end):
            print(f"{j}: {lines[j]}")
        break
else:
    print("No 'Test input' found in session - this confirms it's in original prompt")

print("\n--- Session message types ---")
from collections import Counter
types = Counter()
for line in content.split('\n'):
    if line.startswith('{"type":'):
        line = line.split(',', 1)[0]  # Get the type part
        try:
            value = eval(line).get('type')
            if value:
                types[value] += 1
        except:
            pass
for t, c in sorted(types.items(), key=lambda x: -x[1]):
    print(f"  {t}: {c}")

